import math
import urllib.request
from urllib.parse import urlparse

def download_file_in_parts(
    url: str, 
    output_path: str, 
    max_part_size: int, 
    min_part_size: int = 1048576, 
    max_parts: int = 100
) -> None:
    if not isinstance(url, str) or not isinstance(output_path, str):
        raise TypeError("URL and output path must be strings")

    parsed_url = urlparse(url)
    if parsed_url.scheme not in ('http', 'https'):
        raise ValueError("URL must use HTTP or HTTPS scheme")

    max_part_size = max(max_part_size, min_part_size)

    req = urllib.request.Request(url, method='HEAD')
    try:
        with urllib.request.urlopen(req, timeout=10) as response:
            content_length = response.headers.get('Content-Length')
            if not content_length or not content_length.isdigit():
                raise ValueError("Server did not provide a valid Content-Length header")
            total_size = int(content_length)

            if response.headers.get('Accept-Ranges') != 'bytes':
                raise ValueError("Server does not support Range requests")
    except Exception as e:
        raise RuntimeError(f"Failed to fetch file metadata: {e}")

    num_parts = math.ceil(total_size / max_part_size)
    if num_parts > max_parts:
        num_parts = max_parts
        max_part_size = math.ceil(total_size / num_parts)

    try:
        with open(output_path, 'wb') as f:
            for i in range(num_parts):
                start = i * max_part_size
                end = min(start + max_part_size - 1, total_size - 1)

                part_req = urllib.request.Request(url)
                part_req.add_header('Range', f'bytes={start}-{end}')

                with urllib.request.urlopen(part_req, timeout=30) as part_response:
                    f.write(part_response.read())
