import hashlib
import os
import tempfile
from pathlib import Path

def update_file_version_if_changed(target_file_path: str, version_file_path: str) -> None:
    target_path = Path(target_file_path).resolve()
    version_path = Path(version_file_path).resolve()

    if not target_path.is_file():
        raise FileNotFoundError(f"Target file not found: {target_path}")

    target_hash = hashlib.sha256()
    try:
        with open(target_path, "rb") as f:
            while chunk := f.read(8192):
                target_hash.update(chunk)
    except OSError as e:
        raise RuntimeError(f"Error reading target file: {e}")

    current_hash_hex = target_hash.hexdigest()

    stored_hash_hex = ""
    if version_path.is_file():
        try:
            with open(version_path, "r", encoding="utf-8") as f:
                stored_hash_hex = f.read().strip()
        except OSError as e:
            raise RuntimeError(f"Error reading version file: {e}")

    if current_hash_hex != stored_hash_hex:
        temp_path = None
        try:
            fd, temp_path = tempfile.mkstemp(dir=version_path.parent, prefix=".tmp_version_")
            with os.fdopen(fd, "w", encoding="utf-8") as temp_file:
                temp_file.write(current_hash_hex)

            os.replace(temp_path, version_path)
            os.chmod(version_path, 0o600)
        except OSError as e:
            if temp_path and os.path.exists(temp_path):
                os.remove(temp_path)
            raise RuntimeError(f"Error updating version file: {e}")
